), members as (select space_id,min(user_id::text)::uuid owner_id from public.space_members group by space_id)
insert into public.entries(id,space_id,owner_id,kind,title,visibility,status,details)
select md5(m.space_id::text||':'||i.key)::uuid,m.space_id,m.owner_id,'date',i.title,'shared','pending',i.details::jsonb
from members m cross join ideas i
where not exists(select 1 from public.entries e where e.space_id=m.space_id and e.kind='date' and lower(trim(e.title))=lower(trim(i.title)))
on conflict(id) do nothing;
